pragma solidity ^0.8.0;

import "../../exchange/contracts/periphery/contracts/vendor/uniswap/interfaces/IUniswapV3PositionManager.sol";
import "../../exchange/contracts/periphery/contracts/interfaces/oracle/ISuOracle.sol";

struct WithdrawnToken {
    address tokenAddress;
    uint256 tokenAmount;
}

/**
 * @title IUniswapV3NFTWrapper
 **/
interface IUniswapV3NFTWrapper is ISuOracle {
    // Emitted when a NFT is deposited
    event DepositNFT(uint256 tokenId, uint256 wrapperAmount);
    // Emitted when a NFT is withdrawn
    event WithdrawNFT(uint256 tokenId, uint256 wrapperAmount);
    // Emitted when emergency withdraw
    event EmergencyWithdrawNFT(address[] tokens, uint256[] amounts, address receiver);

    function positionManager() external view returns (IUniswapV3PositionManager);

    function depositNFT(uint256 tokenId, address safeHandler) external returns (uint256);

    function depositNFTFor(uint256 tokenId, address owner, address safeHandler) external returns (uint256);

    function withdrawNFT(
        uint256 tokenId,
        address owner
    ) external returns (address token0, address token1, uint256 amount0, uint256 amount1);

    function withdrawPartial(
        uint256 tokenId,
        uint256 wrapperAmount,
        address owner
    ) external returns (address token0, address token1, uint256 amount0, uint256 amount1);

    function emergencyWithdraw(address[] calldata tokens, uint256[] calldata amounts, address receiver) external;

    /**
     * @notice Withdraws all NFT positions for a user
     * @dev Burns all wrapper tokens for the user and returns all underlying tokens
     * @param user Address of the user whose positions to withdraw
     * @return tokens Array of WithdrawnToken structs containing token addresses and amounts
     */
    function withdrawAllUserNFT(address user) external returns (WithdrawnToken[] memory tokens);
}
